class AtomicJsonStoreError extends Error {
  operation;
  filePath;
  name = "AtomicJsonStoreError";
  constructor(operation, filePath, options) {
    super(`Failed to ${operation} atomic JSON store at ${filePath}`, options);
    this.operation = operation;
