  }
}
function createAtomicJsonStore(filePath) {
  const directory = dirname(filePath);
  const temporary = `${filePath}.${process.pid}.tmp`;
  let writeChain = Promise.resolve();
  return {
    read() {
      try {
        const value = JSON.parse(readFileSync2(filePath, "utf-8"));
        return value;
      } catch (cause) {
        if (cause instanceof Error && "code" in cause && cause.code === "ENOENT") {
          return null;
        }
        throw new AtomicJsonStoreError("read", filePath, { cause });
      }
    },
    write(value) {
      const write = writeChain.catch(() => {
        return;
      }).then(() => {
        try {
          mkdirSync(directory, { recursive: true, mode: 448 });
          writeFileSync2(temporary, JSON.stringify(value), {
            encoding: "utf-8",
            mode: 384
          });
          renameSync(temporary, filePath);
        } catch (cause) {
          try {
            rmSync(temporary, { force: true });
          } catch (cleanupCause) {
            throw new AtomicJsonStoreError("write", filePath, {
              cause: new AggregateError([cause, cleanupCause])
            });
          }
          throw new AtomicJsonStoreError("write", filePath, { cause });
        }
      });
      writeChain = write;
      return write;
    },
    purge() {
      try {
        rmSync(filePath, { force: true });
      } catch (cause) {
        throw new AtomicJsonStoreError("purge", filePath, { cause });
      }
    }
  };
}

